create extension if not exists "uuid-ossp";
create table if not exists roster (index_number text primary key, full_name text);
create table if not exists rep_codes (code text primary key, is_used boolean default false, created_at timestamp default now());
create table if not exists users (id uuid primary key references auth.users(id) on delete cascade, index_number text unique references roster(index_number), name text, role text check (role in ('student','rep')) default 'student', created_at timestamp default now());
create table if not exists timetables (id uuid primary key default uuid_generate_v4(), week_label text, json_data jsonb, image_url text, uploaded_by uuid references users(id), created_at timestamp default now());
create table if not exists materials (id uuid primary key default uuid_generate_v4(), course_code text, week text, type text, title text, file_url text, uploaded_by uuid references users(id), created_at timestamp default now());
create table if not exists announcements (id uuid primary key default uuid_generate_v4(), title text, message text, created_by uuid references users(id), created_at timestamp default now());
create table if not exists anonymous_messages (id uuid primary key default uuid_generate_v4(), course_code text, message text, is_anonymous boolean default true, sender_id uuid references users(id), reply text, created_at timestamp default now());
create table if not exists gpa_records (id uuid primary key default uuid_generate_v4(), user_id uuid references users(id), gpa numeric, semester text, created_at timestamp default now());
insert into roster (index_number) values ('2356866765'),('2356866790'),('2356866788') on conflict do nothing;
create or replace function handle_new_user() returns trigger as $$ declare idx text; rep_code_val text; is_rep boolean := false; begin idx := new.raw_user_meta_data->>'index_number'; rep_code_val := new.raw_user_meta_data->>'rep_code'; if not exists (select 1 from roster where index_number = idx) then raise exception 'Index % not in roster', idx; end if; if rep_code_val is not null and rep_code_val != '' then if exists (select 1 from rep_codes where code = rep_code_val and is_used = false) then is_rep := true; update rep_codes set is_used = true where code = rep_code_val; else raise exception 'Invalid rep code'; end if; end if; insert into public.users (id, index_number, name, role) values (new.id, idx, new.raw_user_meta_data->>'full_name', case when is_rep then 'rep' else 'student' end); return new; end; $$ language plpgsql security definer;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure handle_new_user();
alter table users enable row level security; alter table timetables enable row level security; alter table materials enable row level security; alter table announcements enable row level security; alter table anonymous_messages enable row level security; alter table gpa_records enable row level security;
drop policy if exists "Allow all" on users; drop policy if exists "Allow all" on timetables; drop policy if exists "Allow all" on materials; drop policy if exists "Allow all" on announcements; drop policy if exists "Allow all" on anonymous_messages; drop policy if exists "Allow all" on gpa_records;
create policy "Allow all" on users for all using (true) with check (true); create policy "Allow all" on timetables for all using (true) with check (true); create policy "Allow all" on materials for all using (true) with check (true); create policy "Allow all" on announcements for all using (true) with check (true); create policy "Allow all" on anonymous_messages for all using (true) with check (true); create policy "Allow all" on gpa_records for all using (true) with check (true);
insert into storage.buckets (id, name, public) values ('class-materials','class-materials',true) on conflict do nothing;
drop policy if exists "Public read" on storage.objects; drop policy if exists "Rep upload" on storage.objects; drop policy if exists "Rep delete" on storage.objects;
create policy "Public read" on storage.objects for select using (bucket_id='class-materials'); create policy "Rep upload" on storage.objects for insert with check (bucket_id='class-materials'); create policy "Rep delete" on storage.objects for delete using (bucket_id='class-materials');